from AlgorithmImports import *


class TwoStrategyAlgorithm(QCAlgorithm):
    SMA_PERIOD = 14
    RSI_PERIOD = 14

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = self.SMA(self.spy, self.SMA_PERIOD, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            self.RSI_PERIOD,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.previous_close = {}
        self.previous_sma = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, data):
        available = {}

        for symbol in self.symbols:
            if not data.Bars.ContainsKey(symbol):
                continue

            bar = data.Bars[symbol]
            available[symbol] = bar

            if symbol in self.previous_close:
                if symbol == self.aapl:
                    if bar.Close < self.previous_close[symbol]:
                        self.aapl_red_streak += 1
                    else:
                        self.aapl_red_streak = 0

            self.previous_close[symbol] = bar.Close

        if self.spy not in available:
            return

        spy_bar = available[self.spy]
        spy_sma_value = self.spy_sma.Current.Value if self.spy_sma.IsReady else None

        if not self.spy_sma.IsReady:
            self.previous_sma = spy_sma_value
        elif self.previous_sma is None:
            self.previous_sma = spy_sma_value
        else:
            spy_crosses_below = (
                self.strategy_a_lot > 0
                and spy_bar.Close < spy_sma_value
                and self.previous_close.get(self.spy) is not None
            )

            if self.strategy_a_lot > 0 and spy_crosses_below:
                self.MarketOrder(self.spy, -self.strategy_a_lot)
                self.strategy_a_lot = 0

            if (
                self.strategy_a_lot == 0
                and self.previous_close.get(self.spy) is not None
                and self.previous_sma <= self.previous_close[self.spy]
                and spy_bar.Close > spy_sma_value
            ):
                portfolio_value = self.Portfolio.TotalPortfolioValue
                quantity = int((portfolio_value * 0.40) / spy_bar.Close)

                if quantity > 0:
                    self.MarketOrder(self.spy, quantity)
                    self.strategy_a_lot = quantity

            self.previous_sma = spy_sma_value

        if any(symbol not in available for symbol in self.symbols):
            return

        aapl_bar = available[self.aapl]

        if self.aapl_rsi.IsReady:
            if self.strategy_b_lot > 0 and self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(self.aapl, -self.strategy_b_lot)
                self.strategy_b_lot = 0

            if (
                self.strategy_b_lot == 0
                and self.aapl_red_streak >= 3
                and self.Portfolio.Cash >= 20000
            ):
                quantity = int(20000 / aapl_bar.Close)

                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.strategy_b_lot = quantity

