from AlgorithmImports import *

class ExactStrategySystem(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily
            ).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.sma_period = 20
        self.spy_sma = self.SMA(self.spy, self.sma_period, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self.spy_lot = 0
        self.aapl_lot = 0

        self.previous_spy_sma = None
        self.previous_spy_close = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.SetWarmUp(self.sma_period + 1, Resolution.Daily)

    def OnData(self, data):
        spy_bar = data.Bars[self.spy] if data.Bars.ContainsKey(self.spy) else None
        aapl_bar = data.Bars[self.aapl] if data.Bars.ContainsKey(self.aapl) else None

        current_spy_sma = (
            float(self.spy_sma.Current.Value)
            if self.spy_sma.IsReady else None
        )
        current_aapl_rsi = (
            float(self.aapl_rsi.Current.Value)
            if self.aapl_rsi.IsReady else None
        )

        if aapl_bar is not None:
            if self.previous_aapl_close is not None:
                if float(aapl_bar.Close) < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = float(aapl_bar.Close)

        all_bars_present = all(
            data.Bars.ContainsKey(self.symbols[ticker])
            for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        )

        if not self.IsWarmingUp and all_bars_present:
            if (
                spy_bar is not None
                and current_spy_sma is not None
                and self.previous_spy_sma is not None
                and self.previous_spy_close is not None
            ):
                spy_close = float(spy_bar.Close)

                spy_sell = (
                    self.previous_spy_close >= self.previous_spy_sma
                    and spy_close < current_spy_sma
                )

                spy_buy = (
                    self.previous_spy_close <= self.previous_spy_sma
                    and spy_close > current_spy_sma
                )

                if self.spy_lot > 0 and spy_sell:
                    self.MarketOrder(self.spy, -self.spy_lot)
                    self.spy_lot = 0
                elif self.spy_lot == 0 and spy_buy:
                    quantity = int(
                        (self.Portfolio.TotalPortfolioValue * 0.40)
                        / spy_close
                    )
                    if quantity > 0:
                        self.MarketOrder(self.spy, quantity)
                        self.spy_lot = quantity

            if aapl_bar is not None and current_aapl_rsi is not None:
                aapl_close = float(aapl_bar.Close)

                if self.aapl_lot > 0 and current_aapl_rsi > 60:
                    self.MarketOrder(self.aapl, -self.aapl_lot)
                    self.aapl_lot = 0
                elif self.aapl_lot == 0 and self.aapl_red_streak >= 3:
                    if self.Portfolio.Cash >= 20000:
                        quantity = int(20000 / aapl_close)
                        if quantity > 0:
                            self.MarketOrder(self.aapl, quantity)
                            self.aapl_lot = quantity

        if spy_bar is not None:
            self.previous_spy_close = float(spy_bar.Close)

        if current_spy_sma is not None:
            self.previous_spy_sma = current_spy_sma

