class DailyCrossAndRSIAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = [self.AddEquity(ticker, Resolution.Daily).Symbol for ticker in tickers]

        self.spy = self.symbols[0]
        self.aapl = self.symbols[1]

        self.spy_ma = self.SMA(self.spy, 200, Resolution.Daily)
        self.aapl_rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.previous_closes = {}
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, data: Slice):
        for symbol in self.symbols:
            if symbol in data and data[symbol] is not None:
                close = float(data[symbol].Close)

                if symbol == self.aapl:
                    previous_close = self.previous_closes.get(symbol)
                    if previous_close is not None:
                        if close < previous_close:
                            self.aapl_red_streak += 1
                        else:
                            self.aapl_red_streak = 0

                self.previous_closes[symbol] = close

        if not all(symbol in data and data[symbol] is not None for symbol in self.symbols):
            return

        if not self.spy_ma.IsReady or not self.aapl_rsi.IsReady:
            return

        spy_close = float(data[self.spy].Close)
        aapl_close = float(data[self.aapl].Close)

        previous_spy_close = self.previous_closes.get(("previous", self.spy))
        previous_spy_ma = getattr(self, "previous_spy_ma", None)

        if self.strategy_a_lot > 0:
            if (
                previous_spy_close is not None
                and previous_spy_ma is not None
                and previous_spy_close >= previous_spy_ma
                and spy_close < float(self.spy_ma.Current.Value)
            ):
                self.MarketOrder(self.spy, -self.strategy_a_lot)
                self.strategy_a_lot = 0

        if self.strategy_b_lot > 0:
            if float(self.aapl_rsi.Current.Value) > 60:
                self.MarketOrder(self.aapl, -self.strategy_b_lot)
                self.strategy_b_lot = 0

        if self.strategy_a_lot == 0:
            if (
                previous_spy_close is not None
                and previous_spy_ma is not None
                and previous_spy_close <= previous_spy_ma
                and spy_close > float(self.spy_ma.Current.Value)
            ):
                quantity = floor(
                    (0.40 * self.Portfolio.TotalPortfolioValue) / spy_close
                )
                if quantity > 0:
                    self.MarketOrder(self.spy, quantity)
                    self.strategy_a_lot = quantity

        if self.strategy_b_lot == 0:
            if self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20000:
                quantity = floor(20000 / aapl_close)
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.strategy_b_lot = quantity

        self.previous_closes[("previous", self.spy)] = spy_close
        self.previous_spy_ma = float(self.spy_ma.Current.Value)

