from AlgorithmImports import *
from datetime import datetime


class TwoStrategyAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.spy_sma = SimpleMovingAverage(20)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_prev_close = None
        self.spy_prev_sma = None
        self.aapl_prev_rsi = None

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.SetWarmUp(20, Resolution.Daily)

    def OnData(self, data: Slice):
        symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        if any(symbol not in data.Bars for symbol in symbols):
            return

        spy_bar = data.Bars[self.spy]
        aapl_bar = data.Bars[self.aapl]

        self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)
        self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            self.spy_prev_close = spy_bar.Close
            self.spy_prev_sma = self.spy_sma.Current.Value
            self.aapl_prev_rsi = self.aapl_rsi.Current.Value
            return

        spy_close = spy_bar.Close
        spy_sma = self.spy_sma.Current.Value
        aapl_rsi = self.aapl_rsi.Current.Value

        if self.spy_prev_close is not None and self.strategy_a_lot > 0:
            if self.spy_prev_close >= self.spy_prev_sma and spy_close < spy_sma:
                self.MarketOnCloseOrder(
                    self.spy,
                    -self.strategy_a_lot,
                    tag="Strategy A sell"
                )

        if self.aapl_prev_rsi is not None and self.strategy_b_lot > 0:
            if aapl_rsi > 60:
                self.MarketOnCloseOrder(
                    self.aapl,
                    -self.strategy_b_lot,
                    tag="Strategy B sell"
                )

        if self.strategy_a_lot == 0:
            if self.spy_prev_close is not None:
                if self.spy_prev_close <= self.spy_prev_sma and spy_close > spy_sma:
                    quantity = int((self.Portfolio.TotalPortfolioValue * 0.40) / spy_close)
                    if quantity > 0:
                        self.MarketOnCloseOrder(
                            self.spy,
                            quantity,
                            tag="Strategy A buy"
                        )

        if self.strategy_b_lot == 0:
            if self.aapl_prev_close is not None:
                if (
                    self.aapl_prev_close > 0
                    and aapl_bar.Close < self.aapl_prev_close
                    and self.aapl_red_streak >= 2
                ):
                    if self.Portfolio.Cash >= 20000:
